/** Shared types for World Radar — safe to import from client components. */
import { tMessage } from "@/lib/i18n-pick-message"
import type { AppLocale } from "@/lib/i18n-locale"

/**
 * Where the DATA of a Radar payload really comes from (never how it was served):
 *   live   every row comes from a real source (Affisell listings, a real API call).
 *   mixed  real rows AND simulated rows in the same payload.
 *   demo   hand-written sample records (fallback when the radar database is unreachable).
 *   mock   generated by the deterministic scoring engine (lib/radar/scoring-engine.ts): hashed jitter, no external data.
 * Only `live` may be shown with a LIVE badge, and `isLive` additionally requires a fresh scan.
 */
export type RadarDataSource = "live" | "mixed" | "demo" | "mock"

/** How a payload was served (a cache hit, a scan made for this request, or the generator) — NOT its provenance. */
export type RadarServedFrom = "cache" | "scan" | "mock"

/** Language-neutral banner code the UI translates. `null` = real data, nothing to warn about. */
export type RadarDataNotice = "demo" | "mock" | "mixed" | null

/**
 * Winner `source` values written by a REAL provider (lib/radar/world-scanner.ts): the Affisell listing catalogue and the
 * Serper (Google) keyword API. Anything else stored in the radar tables — the simulated labels "Signaux …" / "Démo …",
 * or the marketplace names an older seed wrote — is NOT proof of a real crawl and is treated as simulated.
 */
export const REAL_WINNER_SOURCES: readonly string[] = ["Affisell", "Google"]

export function isRealWinnerSource(source: string | null | undefined): boolean {
  return REAL_WINNER_SOURCES.includes((source ?? "").trim())
}

/** Provenance of a set of winners, from their `source` labels. An empty set has no provenance: `mock`. */
export function classifyWinnersOrigin(winners: ReadonlyArray<{ source: string }>): RadarDataSource {
  if (winners.length === 0) return "mock"
  const real = winners.filter((w) => isRealWinnerSource(w.source)).length
  if (real === winners.length) return "live"
  return real === 0 ? "mock" : "mixed"
}

export function noticeForSource(source: RadarDataSource): RadarDataNotice {
  if (source === "live") return null
  if (source === "mixed") return "mixed"
  return source === "demo" ? "demo" : "mock"
}

export type SupplierMatchDto = {
  count: number
  sampleNames: string[]
}

export type ArbitrageDto = {
  score: number
  tier: "or" | "argent" | "bronze" | "none"
  label: string
  hint: string
  /** No-stock hover explanation */
  tooltip?: string
}

export type SaturationDto = {
  index: number
  tier: "vierge" | "tot" | "sature"
  label: string
  emoji: string
  daysUntilSaturation: number | null
  prediction: string | null
  barPercent: number
}

export type WorldRadarWinnerDto = {
  id: string
  countryCode: string
  rank: number
  title: string
  image: string | null
  source: string
  price: number | null
  currency: string
  /**
   * True when market/list price was redacted for SUPPLIER (Price Veil).
   * Client must not invent a reseller price from other fields.
   */
  priceVeiled?: boolean
  growthRate: number | null
  searches: number | null
  competition: number | null
  trendingScore: number
  category: string | null
  /** V2 rotation / cultural flags */
  productId?: string
  isNew?: boolean
  isHot?: boolean
  isLocalWinner?: boolean
  lastWeekRank?: number | null
  finalScore?: number
  supplierLabel?: string
  /** Moat 1 — Arbitrage Score™ */
  arbitrage?: ArbitrageDto
  /** Moat 2 — Saturation Index */
  saturation?: SaturationDto
  /** Moat 3 — Affisell FR supplier match */
  supplierMatch?: SupplierMatchDto
  /** True when this row was generated by the simulation, not read from a real source (see `isRealWinnerSource`). */
  synthetic?: boolean
}

export type WorldRadarTrendingDto = {
  id: string
  keyword: string
  growthRate: number
  volume: number | null
}

export type WorldRadarCountryDto = {
  code: string
  name: string
  flag: string
  region: string
  currency: string
  enabled: boolean
  productCount: number
  /** `null` when the country was never really scanned (a simulated payload never sets it). */
  lastScanAt: string | null
  /** True only for real data scanned less than an hour ago. */
  isLive: boolean
}

export type WorldRadarPayload = {
  winners: WorldRadarWinnerDto[]
  trendingKeywords: WorldRadarTrendingDto[]
  country: WorldRadarCountryDto
  lastScanAt: string | null
  /** True only when `source === "live"` AND the scan is fresh (< 1 h). A simulated payload is never live. */
  isLive: boolean
  /** Provenance of the data — truthful. */
  source: RadarDataSource
  /** How it was served (cache / scan for this request / generator). */
  servedFrom: RadarServedFrom
  /** `source !== "live"`: the UI must say it is not real data. */
  isDemo: boolean
  /** Banner code for the UI (`null` for real data). */
  dataNotice: RadarDataNotice
}

export type WorldRadarCountriesPayload = {
  countries: WorldRadarCountryDto[]
  byRegion: Record<string, WorldRadarCountryDto[]>
  total: number
  /** `live` = scan dates / counts read from the radar tables; `mock` = the radar database is unreachable (nothing was scanned). */
  source: "live" | "mock"
}

export type RadarBadgeKind = "demo" | "live" | "cache"

/**
 * Which badge the terminal shows. "live" ONLY for real AND fresh data; anything the server flags as demo is "demo" even if a
 * scan date is present; no payload yet (loading) or stale real data is "cache". Pure, so the rule is unit-tested.
 */
export function radarBadgeKind(
  payload: Partial<Pick<WorldRadarPayload, "isLive" | "isDemo">> | null | undefined
): RadarBadgeKind {
  if (!payload) return "cache"
  if (payload.isDemo === true) return "demo"
  return payload.isLive === true ? "live" : "cache"
}

/** Builds the honesty fields of a payload from the provenance and the scan date. Pure. */
export function radarPayloadFlags(
  source: RadarDataSource,
  lastScanAt: Date | string | null | undefined
): Pick<WorldRadarPayload, "isLive" | "isDemo" | "dataNotice"> {
  return {
    isLive: source === "live" && isCountryScanLive(lastScanAt),
    isDemo: source !== "live",
    dataNotice: noticeForSource(source),
  }
}

export const WORLD_RADAR_CACHE_TTL_MS = 6 * 60 * 60 * 1000

export function isCountryScanLive(lastScanAt: Date | string | null | undefined): boolean {
  if (!lastScanAt) return false
  const ts = typeof lastScanAt === "string" ? new Date(lastScanAt).getTime() : lastScanAt.getTime()
  return Date.now() - ts < 60 * 60 * 1000
}

export function formatRelativeScan(
  lastScanAt: Date | string | null | undefined,
  locale: AppLocale = "fr"
): string {
  const tr = (key: string, n?: number) =>
    tMessage(locale, `radarTerminal.${key}`).replace("{n}", String(n ?? ""))
  if (!lastScanAt) return tr("scanNever")
  const ts = typeof lastScanAt === "string" ? new Date(lastScanAt).getTime() : lastScanAt.getTime()
  const diffMin = Math.max(0, Math.floor((Date.now() - ts) / 60_000))
  if (diffMin < 1) return tr("scanNow")
  if (diffMin < 60) return tr("scanMin", diffMin)
  const h = Math.floor(diffMin / 60)
  if (h < 24) return tr("scanHours", h)
  return tr("scanDays", Math.floor(h / 24))
}
